TRIGGERED_ABILITY.RESOLUTION_TIME_ACTION:
local effectController = EffectController()
local numPlayers = MTG():GetNumberOfPlayers() local lifeToGain = 0
for i = 0, (numPlayers-1) do local currentPlayer = MTG():GetNthPlayer(i) if currentPlayer ~= nil and currentPlayer:GetTeam() ~= effectController:GetTeam() then local lifeLost = currentPlayer:LoseLife(1) lifeToGain = lifeToGain+lifeLost end end effectController:GainLife(lifeToGain)
